"""RULER NIAH tasks over data generated by NVIDIA's OFFICIAL RULER scripts (external/RULER, scripts/data/synthetic/niah.py)
with the Llama-2 tokenizer: exact official sizing (binary search to max_seq_length incl. 128 gen tokens), official
essay haystack, official key/value generators and the official template + answer prefix. Scoring reuses lm-eval's
ruler common_utils (string_match_all, per-length aggregation). Data layout: external/RULER/data_official/<task>_<L>/validation.jsonl
"""
import json, os, datasets
ROOT = os.environ.get("RULER_OFFICIAL_DATA", os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "..", "external", "RULER", "data_official"))
DEFAULT_LENGTHS = [1024, 2048, 4096, 8192]

def _load(task, **kwargs):
    lengths = kwargs.pop("max_seq_lengths", DEFAULT_LENGTHS)
    docs = []
    for L in lengths:
        p = os.path.join(ROOT, f"{task}_{L}", "validation.jsonl")
        if not os.path.exists(p):
            continue
        for line in open(p):
            d = json.loads(line)
            docs.append({"input": d["input"].rstrip("\n"), "outputs": d["outputs"],
                         "gen_prefix": d["answer_prefix"].strip(), "max_length": int(L),
                         "length": d.get("length"), "index": d.get("index")})
    assert docs, f"no official RULER data for {task} at {lengths} under {ROOT}"
    return {"test": datasets.Dataset.from_list(docs, split=datasets.Split.TEST)}

def niah_single_1(**k): return _load("niah_single_1", **k)
def niah_single_2(**k): return _load("niah_single_2", **k)
def niah_single_3(**k): return _load("niah_single_3", **k)
def niah_multikey_1(**k): return _load("niah_multikey_1", **k)
def niah_multikey_2(**k): return _load("niah_multikey_2", **k)
def niah_multikey_3(**k): return _load("niah_multikey_3", **k)

# re-export lm-eval's RULER scorers so the yamls can reference them relative to this directory
from lm_eval.tasks.ruler.common_utils import process_results, aggregate_metrics  # noqa: E402,F401
